package main
import("go/ast";"go/parser";"go/token";"go/format";"os";"path/filepath")
func main(){paths,_:=filepath.Glob("pkg/sim/*.go");for _,p:=range paths{set:=token.NewFileSet();f,err:=parser.ParseFile(set,p,nil,parser.ParseComments);if err!=nil{panic(err)};key:=func(c *ast.CompositeLit){if len(c.Elts)!=2{return};if _,ok:=c.Elts[0].(*ast.KeyValueExpr);ok{return};c.Elts[0]=&ast.KeyValueExpr{Key:ast.NewIdent("X"),Value:c.Elts[0]};c.Elts[1]=&ast.KeyValueExpr{Key:ast.NewIdent("Y"),Value:c.Elts[1]}};ast.Inspect(f,func(n ast.Node)bool{c,ok:=n.(*ast.CompositeLit);if !ok{return true};if id,ok:=c.Type.(*ast.Ident);ok&&id.Name=="Vec"{key(c)};if a,ok:=c.Type.(*ast.ArrayType);ok{if id,ok:=a.Elt.(*ast.Ident);ok&&id.Name=="Vec"{for _,v:=range c.Elts{if inner,ok:=v.(*ast.CompositeLit);ok{key(inner)}}}};return true});out,err:=os.Create(p);if err!=nil{panic(err)};if err=format.Node(out,set,f);err!=nil{panic(err)};out.Close()}}
